    var info = [p.drafted ? "Drafted " + p.drafted[0] + " by " + p.drafted[3] + " with pick " + p.drafted[2] + " in this league." : "", p.rd ? "In real life: drafted " + p.rd[0] + (p.rd[1] ? ", round " + p.rd[1] : "") + (p.rd[2] && p.rd[2] < 600 ? ", pick " + p.rd[2] : "") + " by " + (D.fr[p.rd[3]] ? D.fr[p.rd[3]][D.fr[p.rd[3]].length - 1] : "") + "." : (p.real || p.xr ? "In real life: international signing." : "")].filter(Boolean).join(" ");
    h += '<p class="dim">' + (info ? info + " " : "") + "Prospects have an overall and potential only. Full ratings and stats start when he is called up.</p>";
    var acts = "";
