    if (!Object.keys(G.ps).length) return h + '<div class="card"><p class="dim">Leaders appear once games are played.</p></div>';
    LCAT.forEach(function (c) { var exp = ldExp === c[0], top = leaderList(c[0], ldLg, exp ? 25 : 5);
      h += '<div class="lhead"><span>' + c[0] + (c[2] ? " <small>qualified</small>" : "") + '</span><button class="lnk" data-ldexp="' + c[0] + '">' + (exp ? "Top 5" : "Top 25") + "</button></div><div class=\"group\">" + (top.length ? top.map(function (x, i) { var p = P(x[0]); return '<button class="lrow' + (G.ps[x[0]].tm === G.user ? " me" : "") + '" data-pl="' + x[0] + '"><span class="ord">' + (i + 1) + '</span><span class="pn"><b>' + esc(p.n) + "</b><small>" + G.ps[x[0]].tm + '</small></span><b class="lv">' + x[1] + "</b></button>"; }).join("") : '<div class="news dim">No qualified players yet.</div>') + "</div>"; });
    return h;
