    if (tsView === "bat") { var hs = ids.filter(function (id) { return P(id).k === "H" && G.ps[id].pa; }).sort(function (a, b) { return G.ps[b].pa - G.ps[a].pa; });
      h += '<div class="group">' + tw('<table class="tbl"><tr><th class="l">Player</th><th>G</th><th>PA</th><th>AB</th><th>R</th><th>H</th><th>2B</th><th>3B</th><th>HR</th><th>RBI</th><th>BB</th><th>SO</th><th>SB</th><th class="sep">AVG</th><th>OBP</th><th>SLG</th><th>OPS</th></tr>' + hs.map(function (id) { var s = G.ps[id], o = obp(s), g = slg(s);
        return '<tr data-pl="' + id + '"><td class="l">' + esc(P(id).n) + "</td><td>" + s.g + "</td><td>" + s.pa + "</td><td>" + s.ab + "</td><td>" + s.r + "</td><td>" + s.h + "</td><td>" + s.d + "</td><td>" + s.t + "</td><td>" + s.hr + "</td><td>" + s.rbi + "</td><td>" + s.bb + "</td><td>" + s.so + "</td><td>" + s.sb + '</td><td class="sep">' + f3b(s.h / Math.max(1, s.ab)) + "</td><td>" + f3b(o) + "</td><td>" + f3b(g) + "</td><td>" + f3b(o + g) + "</td></tr>"; }).join("") + "</table>") + "</div>"; }
    else { var ps = ids.filter(function (id) { return P(id).k === "P" && G.ps[id].outs; }).sort(function (a, b) { return G.ps[b].outs - G.ps[a].outs; });
      h += '<div class="group">' + tw('<table class="tbl"><tr><th class="l">Pitcher</th><th>G</th><th>GS</th><th>CG</th><th>SHO</th><th>W</th><th>L</th><th>SV</th><th>IP</th><th>H</th><th>ER</th><th>HR</th><th>BB</th><th>SO</th><th class="sep">ERA</th><th>WHIP</th><th>K/9</th><th>BB/9</th></tr>' + ps.map(function (id) { var s = G.ps[id];
        return '<tr data-pl="' + id + '"><td class="l">' + esc(P(id).n) + "</td><td>" + s.g + "</td><td>" + s.gs + "</td><td>" + (s.cg || 0) + "</td><td>" + (s.sho || 0) + "</td><td>" + s.w + "</td><td>" + s.l + "</td><td>" + s.sv + "</td><td>" + ip(s.outs) + "</td><td>" + s.ph + "</td><td>" + s.er + "</td><td>" + s.phr + "</td><td>" + s.pbb + "</td><td>" + s.pso + '</td><td class="sep">' + era(s) + "</td><td>" + whip(s).toFixed(2) + "</td><td>" + (27 * s.pso / s.outs).toFixed(1) + "</td><td>" + (27 * s.pbb / s.outs).toFixed(1) + "</td></tr>"; }).join("") + "</table>") + "</div>"; }
